contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // avoid triggering C's internal overflow assert: the caller has no prior balance here,
        // and a successful deposit requires amount + 0 > 0, i.e. amount > 0 is not needed
        // because 0 > 0 is false and would revert in C. So require amount > 0.
        require(amount > 0);
        uint256 beforeBal = address(c).balance;
        bool reverted;
        c.deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterBal = address(c).balance;
        assert(!reverted && afterBal == beforeBal + amount);
    }

    receive() external payable {}
}

